import { useState, useCallback, useEffect } from "react";
import { useAuth } from "@clerk/react";
import { useLocation } from "wouter";
import { Bell, CheckCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { EmptyState } from "@/components/empty-state";
import { OwnerLayout, useFacilityId } from "@/components/owner-layout";

type Notif = {
  id: number;
  userId: string;
  type: string;
  title: string;
  body: string;
  link: string | null;
  read: boolean;
  createdAt: string;
};

function timeAgo(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "ką tik";
  if (mins < 60) return `prieš ${mins} min`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `prieš ${hrs} val`;
  const days = Math.floor(hrs / 24);
  return `prieš ${days} d`;
}

function typeIcon(type: string) {
  switch (type) {
    case "booking_created": return "📅";
    case "booking_cancelled": return "❌";
    case "court_approved": return "✅";
    case "court_rejected": return "🚫";
    case "facility_approved": return "✅";
    case "facility_rejected": return "🚫";
    case "coach_approved": return "✅";
    case "coach_rejected": return "🚫";
    case "court_coach_approved": return "✅";
    case "court_coach_rejected": return "🚫";
    case "coach_invite": return "👤";
    case "coach_application": return "📋";
    case "tournament_pending_review": return "🏆";
    case "tournament_approved": return "✅";
    case "tournament_rejected": return "🚫";
    default: return "🔔";
  }
}

function typeLabel(type: string) {
  switch (type) {
    case "booking_created": return "Nauja rezervacija";
    case "booking_cancelled": return "Rezervacija atšaukta";
    case "court_approved": return "Kortas patvirtintas";
    case "court_rejected": return "Kortas atmestas";
    case "facility_approved": return "Aikštelė patvirtinta";
    case "facility_rejected": return "Aikštelė atmesta";
    case "coach_approved": return "Treneris patvirtintas";
    case "coach_rejected": return "Treneris atmestas";
    case "court_coach_approved": return "Kortui priskirtas treneris";
    case "court_coach_rejected": return "Kortui treneris atmestas";
    case "coach_invite": return "Kvietimas treneriui";
    case "coach_application": return "Paraiška trenerio";
    case "tournament_pending_review": return "Turnyras laukia peržiūros";
    case "tournament_approved": return "Turnyras patvirtintas";
    case "tournament_rejected": return "Turnyras atmestas";
    default: return "Pranešimas";
  }
}

const PAGE_SIZE = 20;

function OwnerNotificationsContent() {
  const { getToken } = useAuth();
  const [, setLocation] = useLocation();
  const [notifs, setNotifs] = useState<Notif[]>([]);
  const [loading, setLoading] = useState(true);
  const [markingAll, setMarkingAll] = useState(false);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(false);

  const authFetch = useCallback(async (url: string, options?: RequestInit) => {
    const token = await getToken();
    const headers = new Headers(options?.headers);
    if (token) headers.set("Authorization", `Bearer ${token}`);
    return fetch(url, { ...options, headers, credentials: "include" });
  }, [getToken]);

  const fetchPage = useCallback(async (pageIndex: number, replace: boolean) => {
    setLoading(true);
    try {
      const res = await authFetch(`/api/owner/notifications?limit=${PAGE_SIZE + 1}&offset=${pageIndex * PAGE_SIZE}`);
      if (!res.ok) return;
      const data: Notif[] = await res.json();
      const hasNext = data.length > PAGE_SIZE;
      setHasMore(hasNext);
      const items = hasNext ? data.slice(0, PAGE_SIZE) : data;
      setNotifs(prev => replace ? items : [...prev, ...items]);
    } finally {
      setLoading(false);
    }
  }, [authFetch]);

  useEffect(() => {
    fetchPage(0, true);
  }, [fetchPage]);

  async function handleClick(n: Notif) {
    if (!n.read) {
      setNotifs(prev => prev.map(x => x.id === n.id ? { ...x, read: true } : x));
      authFetch(`/api/notifications/${n.id}/read`, { method: "PATCH" }).catch(() => {});
    }
    if (n.link) setLocation(n.link);
  }

  async function markAllRead() {
    setMarkingAll(true);
    try {
      await authFetch(`/api/owner/notifications/read-all`, { method: "POST" });
      setNotifs(prev => prev.map(n => ({ ...n, read: true })));
