28	/** GET /notifications — fetch notifications for the authenticated user (newest first) */
29	router.get("/notifications", requireAuth, async (req, res): Promise<void> => {
30	  const { userId } = getAuth(req);
31	  const limit = Math.min(Number(req.query.limit) || 50, 200);
32	  const offset = Number(req.query.offset) || 0;
33	
34	  const rows = await db
35	    .select()
36	    .from(notificationsTable)
37	    .where(eq(notificationsTable.userId, userId!))
38	    .orderBy(desc(notificationsTable.createdAt))
39	    .limit(limit)
40	    .offset(offset);
41	
42	  res.set("Cache-Control", "no-store");
43	  res.json(rows);
44	});
45	
46	/** GET /owner/notifications — fetch owner-specific notifications for the authenticated owner */
47	router.get("/owner/notifications", requireOwner, async (req, res): Promise<void> => {
48	  const { userId } = getAuth(req);
49	  const limit = Math.min(Number(req.query.limit) || 100, 200);
50	  const offset = Number(req.query.offset) || 0;
51	
52	  const rows = await db
53	    .select()
54	    .from(notificationsTable)
55	    .where(
56	      and(
57	        eq(notificationsTable.userId, userId!),
58	        inArray(notificationsTable.type, OWNER_NOTIF_TYPES),
59	      )
60	    )
61	    .orderBy(desc(notificationsTable.createdAt))
62	    .limit(limit)
63	    .offset(offset);
64	
65	  res.set("Cache-Control", "no-store");
66	  res.json(rows);
67	});
